/**
 * Debounce: within wait, collapse multiple calls into one.
 * Options:
 *  - leading: call on the leading edge
 *  - trailing: call on the trailing edge (default true)
 */
function debounce(fn, wait = 0, options = {}) {
  const leading = !!options.leading;
  const trailing = options.trailing !== false; // default true

  let timerId = null;
  let lastArgs;
  let lastThis;
  let lastCallTime = 0;
  let lastResult;

  function invoke() {
    timerId = null;
    // trailing edge: only invoke if we actually have pending args
    if (trailing && lastArgs) {
      const args = lastArgs;
      const ctx = lastThis;
      lastArgs = lastThis = null;
      lastResult = fn.apply(ctx, args);
    } else {
      lastArgs = lastThis = null;
    }
    return lastResult;
  }

  function debounced(...args) {
    const now = Date.now();
    lastArgs = args;
    lastThis = this;
    lastCallTime = now;

    const shouldCallLeading = leading && timerId === null;

    if (timerId !== null) clearTimeout(timerId);
    timerId = setTimeout(invoke, wait);

    if (shouldCallLeading) {
      // leading edge: call immediately, but still keep a timer for trailing if enabled
      const args0 = lastArgs;
      const ctx0 = lastThis;
      // If both leading & trailing are true, we should NOT clear lastArgs here,
      // because we want a trailing call only if there are later calls.
      // So we clear only for leading-only case.
      if (!trailing) lastArgs = lastThis = null;

      lastResult = fn.apply(ctx0, args0);
    }

    return lastResult;
  }

  debounced.cancel = function cancel() {
    if (timerId !== null) clearTimeout(timerId);
    timerId = null;
    lastArgs = lastThis = null;
  };

  debounced.flush = function flush() {
    if (timerId === null) return lastResult;
    clearTimeout(timerId);
    return invoke();
  };

  return debounced;
}

/**
 * Throttle: at most once per wait.
 * Options:
 *  - leading: call on the leading edge (default true)
 *  - trailing: call on the trailing edge (default true)
 */
function throttle(fn, wait = 0, options = {}) {
  const leading = options.leading !== false;  // default true
  const trailing = options.trailing !== false; // default true

  let timerId = null;
  let lastArgs;
  let lastThis;
  let lastInvokeTime = 0;
  let lastResult;

  function invoke(time) {
    lastInvokeTime = time;
    const args = lastArgs;
    const ctx = lastThis;
    lastArgs = lastThis = null;
    lastResult = fn.apply(ctx, args);
    return lastResult;
  }

  function startTimer(remaining) {
    timerId = setTimeout(() => {
      timerId = null;
      const now = Date.now();
      // trailing edge
      if (trailing && lastArgs) invoke(now);
    }, remaining);
  }

  function throttled(...args) {
    const now = Date.now();
    if (!lastInvokeTime && !leading) lastInvokeTime = now; // 禁用 leading 时，起点从现在算

    const remaining = wait - (now - lastInvokeTime);

    lastArgs = args;
    lastThis = this;

    if (remaining <= 0 || remaining > wait) {
      if (timerId) {
        clearTimeout(timerId);
        timerId = null;
      }
      // leading edge (or time window passed)
      return invoke(now);
    }

    // schedule trailing if needed
    if (timerId === null && trailing) {
      startTimer(remaining);
    }

    return lastResult;
  }

  throttled.cancel = function cancel() {
    if (timerId) clearTimeout(timerId);
    timerId = null;
    lastArgs = lastThis = null;
    lastInvokeTime = 0;
  };

  throttled.flush = function flush() {
    if (timerId === null) return lastResult;
    clearTimeout(timerId);
    timerId = null;
    const now = Date.now();
    if (lastArgs) return invoke(now);
    return lastResult;
  };

  return throttled;
}
